var Widget = {
  init: function (width, height) {
    this.width = width || 50;
    this.height = height || 50;
  },
  insert: function (el) {
    console.log('Inserting widget with size ' + this.width + 'x' + this.height);
  },
};
var Button = Object.create(Widget);
Button.setup = function (width, height, label) {
  this.init(width, height); // 委托給 Widget.init
  this.label = label || 'Button';
};
Button.build = function () {
  this.insert(); // 委托給 Widget.insert
  console.log('Button label: ' + this.label);
};
var $btn1 = Object.create(Button);
$btn1.setup(125, 30, 'Hello');
$btn1.build();

